import re

_BRACKET_RE = re.compile(
    r"\([^()]*\)"
    r"|\[[^\[\]]*\]"
    r"|\{[^{}]*\}"
    r"|（[^（）]*）"
    r"|【[^【】]*】"
)

def normalize_name(name: str) -> str:
    name = name.lower()
    while True:
        cleaned = _BRACKET_RE.sub("", name)
        if cleaned == name:
            break
        name = cleaned
    return re.sub(r"\s+", "", name)

